import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import ts from "typescript";

const source = await readFile(new URL("../src/lib/publication-checksum.ts", import.meta.url), "utf8");
const compiled = ts.transpileModule(source, {
  compilerOptions: {
    module: ts.ModuleKind.ESNext,
    target: ts.ScriptTarget.ES2022,
  },
}).outputText;
const moduleUrl = `data:text/javascript;base64,${Buffer.from(compiled).toString("base64")}`;
const { verifyPublicationChecksum } = await import(moduleUrl);

// Fixture digest was generated by Python hashlib.sha256(json.dumps(
// envelope_without_checksum, ensure_ascii=False, sort_keys=True).encode("utf-8")).
const validBody = String.raw`{"schema_version": "website_ingest_v1", "publication_id": "project-ä:website", "variant_id": "project-ä:website:pt-PT:default", "project_id": "project-ä", "project_version": "2026-11-12T20:00:00.000000+00:00", "published_at": "2026-11-12T20:05:00.000000+00:00", "payload": {"project_id": "project-ä", "title": "História dos baribudos — ação, coração e 🦊", "price": 9.9, "seo": {"title": "Uma história", "description": "Ação e emoção"}, "assets": {"cover": "https://assets.example/capa.png", "gallery": []}, "manifest": {"ratio": 1.0, "width": 1200, "height": 1600}}, "related_variants": [], "related_projects": [], "asset_manifest": {"items": [{"path": "capa.png", "size": 1024, "scale": 1.25}]}, "branding_pack": null, "marketplace_visuals": {"website": {"hero_background": "", "promo_banners": []}}, "checksum": "3cfac8a75bd7a2807c40bb2c95bd342deec2c9756d48c3cb0bae78f0573a18cc"} `;

test("accepts the Python-generated SHA-256 fixture with Unicode and float tokens", () => {
  assert.equal(verifyPublicationChecksum(validBody), true);
});

test("rejects a payload changed after the checksum was calculated", () => {
  const tampered = validBody.replace("Uma história", "Outra história");
  assert.equal(verifyPublicationChecksum(tampered), false);
});

test("rejects a changed checksum", () => {
  const tampered = validBody.replace("3cfac8a75bd7a2807c40bb2c95bd342deec2c9756d48c3cb0bae78f0573a18cc", "0".repeat(64));
  assert.equal(verifyPublicationChecksum(tampered), false);
});

test("rejects a missing or malformed checksum", () => {
  assert.equal(verifyPublicationChecksum(validBody.replace(/, "checksum": "[a-f0-9]{64}"/, "")), false);
  assert.equal(verifyPublicationChecksum("{not-json"), false);
});

test("does not include the checksum field in the digest", () => {
  const reordered = validBody.replace(
    '"schema_version": "website_ingest_v1", "publication_id":',
    '"publication_id":'
  ).replace(
    '"project_id": "project-ä", "project_version":',
    '"schema_version": "website_ingest_v1", "project_id": "project-ä", "project_version":'
  );
  assert.equal(verifyPublicationChecksum(reordered), true);
});
